"""Module holding the implementation for providing Emil log specific log file on VRAN.
"""
import zipfile
import os


class CloudGnbEmilLogFileProvider:

    """Class to get the trace file for emil logs on VRAN. Currently the output format 5gm is supported.
    """

    def get_emil_log_file(self, log_directory, collector_config):
        log_files = []
        for sub_collector in collector_config['members']:

            sub_log_directory = os.path.join(log_directory, sub_collector)
            dcap_zip_file = os.path.join(sub_log_directory, "dcap.zip")

            with zipfile.ZipFile(file=dcap_zip_file) as dcap_zip:
                log_files_5gm = [filename for filename in dcap_zip.namelist() if filename.endswith("5gm")]

                for log_file in log_files_5gm:
                    dcap_zip.extract(log_file, sub_log_directory)
                log_files += [os.path.join(sub_log_directory, log_file) for log_file in log_files_5gm]

        return log_files
